-- 세트 347: 파일 찾고 한꺼번에 처리하기: find 조건, -exec ; 와 +, xargs -0·-n1, grep -rl | xargs
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_linux_find_xargs_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (347, 1, '이름 패턴으로 파일만 찾아 저장하기 (find -name -type f)', '`/tmp/lab/src` 는 여러 폴더가 겹친 작업 폴더입니다. 이름이 `.log` 로 끝나는 **파일**을 하위 폴더까지 모두 찾아, 경로를 한 줄에 하나씩 **`/tmp/lab/logs.txt`** 에 저장하세요. 이름만 `.log` 이고 실제로는 폴더인 것이 섞여 있으니 걸러야 합니다. 줄 순서는 상관없습니다.', '`find 시작폴더 조건...` 으로 찾습니다. 이름은 `-name ''*.log''` 처럼 따옴표로 감싸 쓰고, 종류는 `-type` 뒤에 파일은 `f`, 폴더는 `d` 를 줍니다. 결과는 `>` 로 파일에 보냅니다. 파일 이름에 공백이 있는 것도 있습니다.', 'find /tmp/lab/src -type f -name ''*.log'' > /tmp/lab/logs.txt
cat /tmp/lab/logs.txt

# -type f 가 없으면 이름이 .log 인 폴더도 같이 나온다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/trash /tmp/lab/backup /tmp/lab/src/sub/deep /tmp/lab/src/sub/rotated.log\\nprintf ''%s\\\\n'' ''a'' > ''/tmp/lab/src/a.log''\\nprintf ''%s\\\\n'' ''b'' > ''/tmp/lab/src/b.log''\\nprintf ''%s\\\\n'' ''remember: set debug=true in the conf files'' > ''/tmp/lab/src/notes.txt''\\nprintf ''%s\\\\n'' ''report'' > ''/tmp/lab/src/my report.txt''\\nprintf ''%s\\\\n'' ''old'' > ''/tmp/lab/src/old data.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/old data.log''\\nprintf ''%s\\\\n'' ''tmp1'' > ''/tmp/lab/src/cache1.tmp''\\nprintf ''%s\\\\n'' ''name=app'' ''debug=true'' > ''/tmp/lab/src/app.conf''\\nprintf ''%s\\\\n'' ''c'' > ''/tmp/lab/src/sub/c.log''\\nprintf ''%s\\\\n'' ''xy'' > ''/tmp/lab/src/sub/x y.log''\\nprintf ''%s\\\\n'' ''tmp2'' > ''/tmp/lab/src/sub/cache2.tmp''\\nprintf ''%s\\\\n'' ''name=db'' ''debug=true'' ''port=1'' > ''/tmp/lab/src/sub/db.conf''\\nhead -c 3000 /dev/zero > ''/tmp/lab/src/sub/big1.dat''\\nprintf ''%s\\\\n'' ''notes'' > ''/tmp/lab/src/sub/old_notes.txt''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/old_notes.txt''\\nprintf ''%s\\\\n'' ''d'' > ''/tmp/lab/src/sub/deep/d.log''\\nprintf ''%s\\\\n'' ''tmp3'' > ''/tmp/lab/src/sub/deep/cache3.tmp''\\nprintf ''%s\\\\n'' ''name=net'' ''debug=false'' > ''/tmp/lab/src/sub/deep/net.conf''\\nhead -c 5000 /dev/zero > ''/tmp/lab/src/sub/deep/big2.dat''\\nprintf ''%s\\\\n'' ''trace'' > ''/tmp/lab/src/sub/deep/old trace.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/deep/old trace.log''\\ntrue"]', '["sh", "-c", "( [ \\"$(LC_ALL=C sort /tmp/lab/logs.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"0f0d95fc8ce9b806af16fafd0a5dbc62\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": ".log 파일 7개의 경로가 들어 있다", "cmd": ["sh", "-c", "[ \\"$(LC_ALL=C sort /tmp/lab/logs.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"0f0d95fc8ce9b806af16fafd0a5dbc62\\" ]"]}]', '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 2, '바로 아래만 찾고 개수 세기 (-maxdepth, wc -l)', '`/tmp/lab/src` **바로 아래**(하위 폴더 안은 제외)에 있는 `.log` 파일이 몇 개인지 세어, **숫자만** **`/tmp/lab/top_count.txt`** 에 저장하세요.', '`-maxdepth 1` 은 시작 폴더에서 한 단계까지만 내려가라는 뜻입니다. 조건의 앞쪽(시작 폴더 바로 뒤)에 두세요. 찾은 줄의 개수는 `wc -l` 로 셀 수 있고, `wc -l` 은 입력이 파이프로 들어오면 숫자만 출력합니다.', 'find /tmp/lab/src -maxdepth 1 -type f -name ''*.log'' | wc -l > /tmp/lab/top_count.txt
cat /tmp/lab/top_count.txt

# -maxdepth 가 없으면 하위 폴더의 .log 까지 세서 7 이 나온다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/trash /tmp/lab/backup /tmp/lab/src/sub/deep /tmp/lab/src/sub/rotated.log\\nprintf ''%s\\\\n'' ''a'' > ''/tmp/lab/src/a.log''\\nprintf ''%s\\\\n'' ''b'' > ''/tmp/lab/src/b.log''\\nprintf ''%s\\\\n'' ''remember: set debug=true in the conf files'' > ''/tmp/lab/src/notes.txt''\\nprintf ''%s\\\\n'' ''report'' > ''/tmp/lab/src/my report.txt''\\nprintf ''%s\\\\n'' ''old'' > ''/tmp/lab/src/old data.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/old data.log''\\nprintf ''%s\\\\n'' ''tmp1'' > ''/tmp/lab/src/cache1.tmp''\\nprintf ''%s\\\\n'' ''name=app'' ''debug=true'' > ''/tmp/lab/src/app.conf''\\nprintf ''%s\\\\n'' ''c'' > ''/tmp/lab/src/sub/c.log''\\nprintf ''%s\\\\n'' ''xy'' > ''/tmp/lab/src/sub/x y.log''\\nprintf ''%s\\\\n'' ''tmp2'' > ''/tmp/lab/src/sub/cache2.tmp''\\nprintf ''%s\\\\n'' ''name=db'' ''debug=true'' ''port=1'' > ''/tmp/lab/src/sub/db.conf''\\nhead -c 3000 /dev/zero > ''/tmp/lab/src/sub/big1.dat''\\nprintf ''%s\\\\n'' ''notes'' > ''/tmp/lab/src/sub/old_notes.txt''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/old_notes.txt''\\nprintf ''%s\\\\n'' ''d'' > ''/tmp/lab/src/sub/deep/d.log''\\nprintf ''%s\\\\n'' ''tmp3'' > ''/tmp/lab/src/sub/deep/cache3.tmp''\\nprintf ''%s\\\\n'' ''name=net'' ''debug=false'' > ''/tmp/lab/src/sub/deep/net.conf''\\nhead -c 5000 /dev/zero > ''/tmp/lab/src/sub/deep/big2.dat''\\nprintf ''%s\\\\n'' ''trace'' > ''/tmp/lab/src/sub/deep/old trace.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/deep/old trace.log''\\ntrue"]', '["sh", "-c", "( [ \\"$(tr -d '' \\\\n'' < /tmp/lab/top_count.txt)\\" = \\"3\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3 이 들어 있다", "cmd": ["sh", "-c", "[ \\"$(tr -d '' \\\\n'' < /tmp/lab/top_count.txt)\\" = \\"3\\" ]"]}]', '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 3, '크기로 찾기 (-size)', '`/tmp/lab/src` 안에서 **1KB 를 넘는 파일**의 경로를 한 줄에 하나씩 **`/tmp/lab/big.txt`** 에 저장하세요.', '`-size` 뒤에 `+` 와 숫자, 단위를 붙입니다. 단위 `k` 는 킬로바이트이고 `+` 는 "그보다 크다" 입니다. 폴더가 섞이지 않게 종류 조건도 함께 주세요.', 'find /tmp/lab/src -type f -size +1k > /tmp/lab/big.txt
cat /tmp/lab/big.txt

# +1k 는 1k 초과, -1k 는 미만이다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/trash /tmp/lab/backup /tmp/lab/src/sub/deep /tmp/lab/src/sub/rotated.log\\nprintf ''%s\\\\n'' ''a'' > ''/tmp/lab/src/a.log''\\nprintf ''%s\\\\n'' ''b'' > ''/tmp/lab/src/b.log''\\nprintf ''%s\\\\n'' ''remember: set debug=true in the conf files'' > ''/tmp/lab/src/notes.txt''\\nprintf ''%s\\\\n'' ''report'' > ''/tmp/lab/src/my report.txt''\\nprintf ''%s\\\\n'' ''old'' > ''/tmp/lab/src/old data.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/old data.log''\\nprintf ''%s\\\\n'' ''tmp1'' > ''/tmp/lab/src/cache1.tmp''\\nprintf ''%s\\\\n'' ''name=app'' ''debug=true'' > ''/tmp/lab/src/app.conf''\\nprintf ''%s\\\\n'' ''c'' > ''/tmp/lab/src/sub/c.log''\\nprintf ''%s\\\\n'' ''xy'' > ''/tmp/lab/src/sub/x y.log''\\nprintf ''%s\\\\n'' ''tmp2'' > ''/tmp/lab/src/sub/cache2.tmp''\\nprintf ''%s\\\\n'' ''name=db'' ''debug=true'' ''port=1'' > ''/tmp/lab/src/sub/db.conf''\\nhead -c 3000 /dev/zero > ''/tmp/lab/src/sub/big1.dat''\\nprintf ''%s\\\\n'' ''notes'' > ''/tmp/lab/src/sub/old_notes.txt''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/old_notes.txt''\\nprintf ''%s\\\\n'' ''d'' > ''/tmp/lab/src/sub/deep/d.log''\\nprintf ''%s\\\\n'' ''tmp3'' > ''/tmp/lab/src/sub/deep/cache3.tmp''\\nprintf ''%s\\\\n'' ''name=net'' ''debug=false'' > ''/tmp/lab/src/sub/deep/net.conf''\\nhead -c 5000 /dev/zero > ''/tmp/lab/src/sub/deep/big2.dat''\\nprintf ''%s\\\\n'' ''trace'' > ''/tmp/lab/src/sub/deep/old trace.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/deep/old trace.log''\\ntrue"]', '["sh", "-c", "( [ \\"$(LC_ALL=C sort /tmp/lab/big.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"a3c637babb3ee81d1bba11c01a16dcf8\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "1KB 넘는 파일 2개만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(LC_ALL=C sort /tmp/lab/big.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"a3c637babb3ee81d1bba11c01a16dcf8\\" ]"]}]', '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 4, '오래된 파일 찾기 (-mtime)', '`/tmp/lab/src` 에는 마지막 수정이 **30일보다 더 지난** 오래된 파일이 몇 개 있습니다. 그 파일들의 경로를 한 줄에 하나씩 **`/tmp/lab/old.txt`** 에 저장하세요. (폴더는 제외합니다.)', '`-mtime +30` 은 마지막 수정이 30일보다 더 전인 것을 뜻합니다. `-mtime 30` 이나 `-30` 과 뜻이 다르니 `+` 를 확인하세요. 종류 조건도 함께 주세요.', 'find /tmp/lab/src -type f -mtime +30 > /tmp/lab/old.txt
cat /tmp/lab/old.txt

# +30 은 30일 초과, -30 은 30일 이내, 30 은 딱 30일 전이다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/trash /tmp/lab/backup /tmp/lab/src/sub/deep /tmp/lab/src/sub/rotated.log\\nprintf ''%s\\\\n'' ''a'' > ''/tmp/lab/src/a.log''\\nprintf ''%s\\\\n'' ''b'' > ''/tmp/lab/src/b.log''\\nprintf ''%s\\\\n'' ''remember: set debug=true in the conf files'' > ''/tmp/lab/src/notes.txt''\\nprintf ''%s\\\\n'' ''report'' > ''/tmp/lab/src/my report.txt''\\nprintf ''%s\\\\n'' ''old'' > ''/tmp/lab/src/old data.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/old data.log''\\nprintf ''%s\\\\n'' ''tmp1'' > ''/tmp/lab/src/cache1.tmp''\\nprintf ''%s\\\\n'' ''name=app'' ''debug=true'' > ''/tmp/lab/src/app.conf''\\nprintf ''%s\\\\n'' ''c'' > ''/tmp/lab/src/sub/c.log''\\nprintf ''%s\\\\n'' ''xy'' > ''/tmp/lab/src/sub/x y.log''\\nprintf ''%s\\\\n'' ''tmp2'' > ''/tmp/lab/src/sub/cache2.tmp''\\nprintf ''%s\\\\n'' ''name=db'' ''debug=true'' ''port=1'' > ''/tmp/lab/src/sub/db.conf''\\nhead -c 3000 /dev/zero > ''/tmp/lab/src/sub/big1.dat''\\nprintf ''%s\\\\n'' ''notes'' > ''/tmp/lab/src/sub/old_notes.txt''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/old_notes.txt''\\nprintf ''%s\\\\n'' ''d'' > ''/tmp/lab/src/sub/deep/d.log''\\nprintf ''%s\\\\n'' ''tmp3'' > ''/tmp/lab/src/sub/deep/cache3.tmp''\\nprintf ''%s\\\\n'' ''name=net'' ''debug=false'' > ''/tmp/lab/src/sub/deep/net.conf''\\nhead -c 5000 /dev/zero > ''/tmp/lab/src/sub/deep/big2.dat''\\nprintf ''%s\\\\n'' ''trace'' > ''/tmp/lab/src/sub/deep/old trace.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/deep/old trace.log''\\ntrue"]', '["sh", "-c", "( [ \\"$(LC_ALL=C sort /tmp/lab/old.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"7e2c030db39ded098c6ec43cda01b70c\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "오래된 파일 3개만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(LC_ALL=C sort /tmp/lab/old.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"7e2c030db39ded098c6ec43cda01b70c\\" ]"]}]', '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 5, '찾은 파일을 한 곳으로 옮기기 (-exec mv)', '`/tmp/lab/src` 아래의 `.tmp` 파일을 모두 **`/tmp/lab/trash`** 폴더로 **옮기세요**. 목록만 적는 것이 아니라 실제로 옮겨져 있어야 합니다. (`.tmp` 파일은 서로 이름이 다릅니다.)', '`find ... -exec 명령 {} 목적지 \\;` 는 찾은 파일마다 `{}` 자리에 파일 이름을 넣어 명령을 실행합니다. 끝에 `\\;` 를 붙여야 find 가 명령의 끝을 압니다. 쉘이 `;` 를 먼저 읽지 않게 앞에 `\\` 를 씁니다.', 'find /tmp/lab/src -type f -name ''*.tmp'' -exec mv {} /tmp/lab/trash/ \\;
ls /tmp/lab/trash

# {} 는 찾은 파일 하나로 바뀌고, \\; 는 명령의 끝을 뜻한다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/trash /tmp/lab/backup /tmp/lab/src/sub/deep /tmp/lab/src/sub/rotated.log\\nprintf ''%s\\\\n'' ''a'' > ''/tmp/lab/src/a.log''\\nprintf ''%s\\\\n'' ''b'' > ''/tmp/lab/src/b.log''\\nprintf ''%s\\\\n'' ''remember: set debug=true in the conf files'' > ''/tmp/lab/src/notes.txt''\\nprintf ''%s\\\\n'' ''report'' > ''/tmp/lab/src/my report.txt''\\nprintf ''%s\\\\n'' ''old'' > ''/tmp/lab/src/old data.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/old data.log''\\nprintf ''%s\\\\n'' ''tmp1'' > ''/tmp/lab/src/cache1.tmp''\\nprintf ''%s\\\\n'' ''name=app'' ''debug=true'' > ''/tmp/lab/src/app.conf''\\nprintf ''%s\\\\n'' ''c'' > ''/tmp/lab/src/sub/c.log''\\nprintf ''%s\\\\n'' ''xy'' > ''/tmp/lab/src/sub/x y.log''\\nprintf ''%s\\\\n'' ''tmp2'' > ''/tmp/lab/src/sub/cache2.tmp''\\nprintf ''%s\\\\n'' ''name=db'' ''debug=true'' ''port=1'' > ''/tmp/lab/src/sub/db.conf''\\nhead -c 3000 /dev/zero > ''/tmp/lab/src/sub/big1.dat''\\nprintf ''%s\\\\n'' ''notes'' > ''/tmp/lab/src/sub/old_notes.txt''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/old_notes.txt''\\nprintf ''%s\\\\n'' ''d'' > ''/tmp/lab/src/sub/deep/d.log''\\nprintf ''%s\\\\n'' ''tmp3'' > ''/tmp/lab/src/sub/deep/cache3.tmp''\\nprintf ''%s\\\\n'' ''name=net'' ''debug=false'' > ''/tmp/lab/src/sub/deep/net.conf''\\nhead -c 5000 /dev/zero > ''/tmp/lab/src/sub/deep/big2.dat''\\nprintf ''%s\\\\n'' ''trace'' > ''/tmp/lab/src/sub/deep/old trace.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/deep/old trace.log''\\ntrue"]', '["sh", "-c", "( [ \\"$(ls /tmp/lab/trash | LC_ALL=C sort | md5sum | cut -d\\" \\" -f1)\\" = \\"1758e18466d255fa525dd464fc70ade4\\" ] ) && ( [ \\"$(find /tmp/lab/src -name ''*.tmp'' | wc -l)\\" -eq 0 ] ) && ( [ \\"$(find /tmp/lab/src -type f | wc -l)\\" -eq 15 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "trash 에 .tmp 3개가 옮겨져 있다", "cmd": ["sh", "-c", "[ \\"$(ls /tmp/lab/trash | LC_ALL=C sort | md5sum | cut -d\\" \\" -f1)\\" = \\"1758e18466d255fa525dd464fc70ade4\\" ]"]}, {"label": "src 에는 .tmp 가 남아 있지 않다", "cmd": ["sh", "-c", "[ \\"$(find /tmp/lab/src -name ''*.tmp'' | wc -l)\\" -eq 0 ]"]}, {"label": "src 의 나머지 파일 15개는 그대로다", "cmd": ["sh", "-c", "[ \\"$(find /tmp/lab/src -type f | wc -l)\\" -eq 15 ]"]}]', '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 6, '-exec 의 \\; 와 + 는 무엇이 다를까?', '`find . -name ''*.tmp'' -exec rm {} \\;` 와 `find . -name ''*.tmp'' -exec rm {} +` 를 비교합니다. `.tmp` 파일이 100개일 때 두 방식의 차이는 무엇일까요?', '`;` 로 끝내는 쪽과 `+` 로 끝내는 쪽 중, 어느 쪽이 `rm` 을 여러 번 실행하고 어느 쪽이 파일 이름을 여럿 모아 한 번에 넘기는지 `{}` 가 들어가는 모양을 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["`\\\\;` 는 파일을 모아 `rm` 한 번에 넘기고, `+` 는 파일마다 `rm` 을 한 번씩 실행한다", "`\\\\;` 는 파일마다 `rm` 을 한 번씩 실행하고, `+` 는 파일을 모아 `rm` 한 번에 넘긴다", "`\\\\;` 는 오류가 나도 계속하고, `+` 는 첫 오류가 나면 전체를 멈춘다", "`\\\\;` 는 파일만 지우고, `+` 는 폴더까지 같이 지워 준다"]', 1, '`\\;` 로 끝내면 찾은 파일마다 명령을 따로 실행하므로 100개면 `rm` 이 100번 돕니다. `+` 로 끝내면 파일 이름을 한꺼번에 이어 붙여 `rm a b c ...` 처럼 몇 번만 실행하므로 빠릅니다. 두 방식 모두 파일/폴더 대상은 `-type` 같은 조건이 정하고, 오류 처리는 이 기호와 상관이 없습니다. `+` 를 쓸 때는 `{}` 가 명령의 맨 끝에 와야 합니다.', NULL, NULL, NULL, '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 7, '여러 파일을 한 번에 복사하기 (-exec cp -t ... +)', '`/tmp/lab/src` 아래의 `.log` **파일**을 모두 **`/tmp/lab/backup`** 폴더로 **복사**하세요. 원본은 그대로 남아야 합니다. 이름이 겹치는 파일은 없습니다.', '`cp` 는 마지막 인자를 목적지로 보는데, `find -exec ... {} +` 는 `{}` 를 맨 끝에 놓아야 합니다. 그래서 목적지를 먼저 적는 옵션(`cp -t 목적지 파일...`)을 씁니다. 폴더가 섞이지 않게 종류 조건을 주세요.', 'find /tmp/lab/src -type f -name ''*.log'' -exec cp -t /tmp/lab/backup {} +
ls /tmp/lab/backup

# -t 는 목적지를 앞에 적게 해서 {} 를 맨 끝에 둘 수 있다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/trash /tmp/lab/backup /tmp/lab/src/sub/deep /tmp/lab/src/sub/rotated.log\\nprintf ''%s\\\\n'' ''a'' > ''/tmp/lab/src/a.log''\\nprintf ''%s\\\\n'' ''b'' > ''/tmp/lab/src/b.log''\\nprintf ''%s\\\\n'' ''remember: set debug=true in the conf files'' > ''/tmp/lab/src/notes.txt''\\nprintf ''%s\\\\n'' ''report'' > ''/tmp/lab/src/my report.txt''\\nprintf ''%s\\\\n'' ''old'' > ''/tmp/lab/src/old data.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/old data.log''\\nprintf ''%s\\\\n'' ''tmp1'' > ''/tmp/lab/src/cache1.tmp''\\nprintf ''%s\\\\n'' ''name=app'' ''debug=true'' > ''/tmp/lab/src/app.conf''\\nprintf ''%s\\\\n'' ''c'' > ''/tmp/lab/src/sub/c.log''\\nprintf ''%s\\\\n'' ''xy'' > ''/tmp/lab/src/sub/x y.log''\\nprintf ''%s\\\\n'' ''tmp2'' > ''/tmp/lab/src/sub/cache2.tmp''\\nprintf ''%s\\\\n'' ''name=db'' ''debug=true'' ''port=1'' > ''/tmp/lab/src/sub/db.conf''\\nhead -c 3000 /dev/zero > ''/tmp/lab/src/sub/big1.dat''\\nprintf ''%s\\\\n'' ''notes'' > ''/tmp/lab/src/sub/old_notes.txt''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/old_notes.txt''\\nprintf ''%s\\\\n'' ''d'' > ''/tmp/lab/src/sub/deep/d.log''\\nprintf ''%s\\\\n'' ''tmp3'' > ''/tmp/lab/src/sub/deep/cache3.tmp''\\nprintf ''%s\\\\n'' ''name=net'' ''debug=false'' > ''/tmp/lab/src/sub/deep/net.conf''\\nhead -c 5000 /dev/zero > ''/tmp/lab/src/sub/deep/big2.dat''\\nprintf ''%s\\\\n'' ''trace'' > ''/tmp/lab/src/sub/deep/old trace.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/deep/old trace.log''\\ntrue"]', '["sh", "-c", "( [ \\"$(ls /tmp/lab/backup | LC_ALL=C sort | md5sum | cut -d\\" \\" -f1)\\" = \\"540eef4da46ac58abff4ae5d41d1fcc1\\" ] ) && ( [ \\"$(find /tmp/lab/src -type f -name ''*.log'' | wc -l)\\" -eq 7 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "backup 에 .log 파일 7개가 있다", "cmd": ["sh", "-c", "[ \\"$(ls /tmp/lab/backup | LC_ALL=C sort | md5sum | cut -d\\" \\" -f1)\\" = \\"540eef4da46ac58abff4ae5d41d1fcc1\\" ]"]}, {"label": "원본 .log 7개는 그대로 남아 있다", "cmd": ["sh", "-c", "[ \\"$(find /tmp/lab/src -type f -name ''*.log'' | wc -l)\\" -eq 7 ]"]}]', '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 8, '공백이 있는 이름을 안전하게 넘기기 (-print0 | xargs -0)', '이름에 공백이 있는 파일도 안전하게 지우려고 합니다. find 는 이름 사이를 **널 문자**로 구분해 내보내고, xargs 는 그것을 받아서 읽어야 합니다. 빈칸에 알맞은 xargs 옵션을 채우세요.', '`find -print0` 은 이름 끝에 줄바꿈 대신 널 문자를 붙입니다. xargs 의 `man` 페이지에서 입력을 널 문자로 구분해 읽는 옵션이 무엇인지 찾아보세요.', NULL, NULL, '[]', 'fill', '["-0", "-n1", "-t", "-r"]', NULL, '`-print0` 과 `xargs -0` 은 짝입니다. 이름 사이를 널 문자로 구분하므로 공백이 있는 `my report.txt` 가 둘로 쪼개지지 않습니다. `-n1` 은 한 번에 인자 하나씩 넘길 뿐 이름은 공백에서 여전히 쪼갭니다. `-t` 는 실행할 명령을 화면에 보여 줄 뿐이고, `-r` 은 입력이 비면 실행하지 않을 뿐입니다. 둘 다 공백 문제를 풀지 못합니다.', '[0]', 'find /tmp/lab/src -type f -name ''* *'' -print0 | xargs {0} rm', NULL, '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 9, '이름에 공백이 있는 파일 지우기 (find -print0 | xargs -0 rm)', '`/tmp/lab/src` 아래에서 **이름에 공백이 들어 있는 파일**을 모두 지우세요. 공백이 없는 이름의 파일은 하나도 지우면 안 됩니다. 이름이 공백에서 쪼개지지 않게 하는 방법으로 풀어 보세요.', '이름 패턴 `-name ''* *''` 로 공백이 든 이름을 고르고, 결과를 `xargs` 로 `rm` 에 넘깁니다. 그냥 `| xargs rm` 은 공백에서 이름이 쪼개지니, find 와 xargs 양쪽에 널 문자 옵션을 짝으로 주세요.', 'find /tmp/lab/src -type f -name ''* *'' -print0 | xargs -0 rm
find /tmp/lab/src -type f

# -print0 과 -0 이 짝이다. 하나만 쓰면 공백이 든 이름이 깨진다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/trash /tmp/lab/backup /tmp/lab/src/sub/deep /tmp/lab/src/sub/rotated.log\\nprintf ''%s\\\\n'' ''a'' > ''/tmp/lab/src/a.log''\\nprintf ''%s\\\\n'' ''b'' > ''/tmp/lab/src/b.log''\\nprintf ''%s\\\\n'' ''remember: set debug=true in the conf files'' > ''/tmp/lab/src/notes.txt''\\nprintf ''%s\\\\n'' ''report'' > ''/tmp/lab/src/my report.txt''\\nprintf ''%s\\\\n'' ''old'' > ''/tmp/lab/src/old data.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/old data.log''\\nprintf ''%s\\\\n'' ''tmp1'' > ''/tmp/lab/src/cache1.tmp''\\nprintf ''%s\\\\n'' ''name=app'' ''debug=true'' > ''/tmp/lab/src/app.conf''\\nprintf ''%s\\\\n'' ''c'' > ''/tmp/lab/src/sub/c.log''\\nprintf ''%s\\\\n'' ''xy'' > ''/tmp/lab/src/sub/x y.log''\\nprintf ''%s\\\\n'' ''tmp2'' > ''/tmp/lab/src/sub/cache2.tmp''\\nprintf ''%s\\\\n'' ''name=db'' ''debug=true'' ''port=1'' > ''/tmp/lab/src/sub/db.conf''\\nhead -c 3000 /dev/zero > ''/tmp/lab/src/sub/big1.dat''\\nprintf ''%s\\\\n'' ''notes'' > ''/tmp/lab/src/sub/old_notes.txt''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/old_notes.txt''\\nprintf ''%s\\\\n'' ''d'' > ''/tmp/lab/src/sub/deep/d.log''\\nprintf ''%s\\\\n'' ''tmp3'' > ''/tmp/lab/src/sub/deep/cache3.tmp''\\nprintf ''%s\\\\n'' ''name=net'' ''debug=false'' > ''/tmp/lab/src/sub/deep/net.conf''\\nhead -c 5000 /dev/zero > ''/tmp/lab/src/sub/deep/big2.dat''\\nprintf ''%s\\\\n'' ''trace'' > ''/tmp/lab/src/sub/deep/old trace.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/deep/old trace.log''\\ntrue"]', '["sh", "-c", "( [ \\"$(find /tmp/lab/src -type f -name ''* *'' | wc -l)\\" -eq 0 ] ) && ( [ \\"$(find /tmp/lab/src -type f | wc -l)\\" -eq 14 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "공백이 든 이름의 파일이 남아 있지 않다", "cmd": ["sh", "-c", "[ \\"$(find /tmp/lab/src -type f -name ''* *'' | wc -l)\\" -eq 0 ]"]}, {"label": "공백 없는 나머지 14개는 그대로다", "cmd": ["sh", "-c", "[ \\"$(find /tmp/lab/src -type f | wc -l)\\" -eq 14 ]"]}]', '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 10, '인자를 하나씩 넘기기 (xargs -n1)', '`/tmp/lab/src` 아래의 `.conf` 파일 이름을 **경로 없이 파일 이름만** 한 줄에 하나씩 **`/tmp/lab/confnames.txt`** 에 저장하세요. 예: `app.conf`. 줄 순서는 상관없습니다. `basename` 은 한 번에 이름 하나만 다룹니다.', '`basename 경로` 는 경로에서 파일 이름만 돌려줍니다. 찾은 경로를 `xargs` 로 넘기되, 한 번 실행에 인자를 하나만 주는 옵션(`-n 1`)을 쓰면 파일마다 `basename` 이 한 번씩 돕니다.', 'find /tmp/lab/src -type f -name ''*.conf'' | xargs -n1 basename > /tmp/lab/confnames.txt
cat /tmp/lab/confnames.txt

# -n1 은 xargs 가 명령을 한 번 실행할 때 인자를 하나만 준다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/trash /tmp/lab/backup /tmp/lab/src/sub/deep /tmp/lab/src/sub/rotated.log\\nprintf ''%s\\\\n'' ''a'' > ''/tmp/lab/src/a.log''\\nprintf ''%s\\\\n'' ''b'' > ''/tmp/lab/src/b.log''\\nprintf ''%s\\\\n'' ''remember: set debug=true in the conf files'' > ''/tmp/lab/src/notes.txt''\\nprintf ''%s\\\\n'' ''report'' > ''/tmp/lab/src/my report.txt''\\nprintf ''%s\\\\n'' ''old'' > ''/tmp/lab/src/old data.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/old data.log''\\nprintf ''%s\\\\n'' ''tmp1'' > ''/tmp/lab/src/cache1.tmp''\\nprintf ''%s\\\\n'' ''name=app'' ''debug=true'' > ''/tmp/lab/src/app.conf''\\nprintf ''%s\\\\n'' ''c'' > ''/tmp/lab/src/sub/c.log''\\nprintf ''%s\\\\n'' ''xy'' > ''/tmp/lab/src/sub/x y.log''\\nprintf ''%s\\\\n'' ''tmp2'' > ''/tmp/lab/src/sub/cache2.tmp''\\nprintf ''%s\\\\n'' ''name=db'' ''debug=true'' ''port=1'' > ''/tmp/lab/src/sub/db.conf''\\nhead -c 3000 /dev/zero > ''/tmp/lab/src/sub/big1.dat''\\nprintf ''%s\\\\n'' ''notes'' > ''/tmp/lab/src/sub/old_notes.txt''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/old_notes.txt''\\nprintf ''%s\\\\n'' ''d'' > ''/tmp/lab/src/sub/deep/d.log''\\nprintf ''%s\\\\n'' ''tmp3'' > ''/tmp/lab/src/sub/deep/cache3.tmp''\\nprintf ''%s\\\\n'' ''name=net'' ''debug=false'' > ''/tmp/lab/src/sub/deep/net.conf''\\nhead -c 5000 /dev/zero > ''/tmp/lab/src/sub/deep/big2.dat''\\nprintf ''%s\\\\n'' ''trace'' > ''/tmp/lab/src/sub/deep/old trace.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/deep/old trace.log''\\ntrue"]', '["sh", "-c", "( [ \\"$(LC_ALL=C sort /tmp/lab/confnames.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"b9d99218720d12ee4a8d4206d4d5d1b7\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": ".conf 파일 이름 3개만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(LC_ALL=C sort /tmp/lab/confnames.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"b9d99218720d12ee4a8d4206d4d5d1b7\\" ]"]}]', '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 11, '지우기 전에 확인하는 순서', '`.tmp` 파일을 찾아 지울 때 실수를 줄이는 작업입니다. 안전하게 진행하는 순서대로, **앞에서 뒤**로 놓으세요.', '지우는 일은 되돌릴 수 없으니, 무엇이 잡히는지 먼저 파일로 남겨 보고 확인한 다음 지웁니다. 마지막에는 정말 다 지워졌는지 같은 조건으로 다시 찾아 봅니다.', NULL, NULL, '[]', 'order', '["`find ... -name ''*.tmp'' > list.txt` 로 지울 대상 목록을 파일에 남긴다", "`wc -l list.txt` 와 `cat list.txt` 로 개수와 이름이 예상과 맞는지 확인한다", "`find ... -name ''*.tmp'' -print0 | xargs -0 rm` 으로 지운다", "같은 `find` 를 다시 실행해 아무것도 나오지 않는지 확인한다"]', NULL, '**목록 저장 → 확인 → 삭제 → 재확인** 순서입니다. 목록이 있어야 확인할 수 있고, 확인이 끝나야 지울 수 있습니다. 지운 뒤에 같은 find 를 다시 돌려 빈 결과가 나와야 정말 다 지워진 것입니다. 삭제를 목록 확인보다 앞에 두면 잘못 잡힌 파일도 이미 지워진 뒤라 되돌릴 수 없습니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]'),
  (347, 12, '내용으로 찾아 한꺼번에 고치기 (grep -rl | xargs sed -i)', '`/tmp/lab/src` 아래의 **`.conf` 파일 중** `debug=true` 가 들어 있는 파일을 찾아, 그 파일들의 `debug=true` 를 **`debug=false`** 로 **직접 고치세요**. `.conf` 가 아닌 파일(예: `notes.txt`)은 `debug=true` 라는 글자가 있어도 건드리면 안 됩니다.', '`grep -rl 글자 폴더` 는 그 글자가 든 파일의 **이름만** 재귀로 출력합니다. `--include=''*.conf''` 로 확장자를 한정할 수 있습니다. 그 목록을 `xargs` 로 받아 `sed -i` 로 파일을 직접 고치세요.', 'grep -rl --include=''*.conf'' ''debug=true'' /tmp/lab/src | xargs sed -i ''s/debug=true/debug=false/''
grep -r ''debug='' /tmp/lab/src

# -l 은 파일 이름만 출력, --include 는 검색할 파일 이름 패턴을 제한한다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/trash /tmp/lab/backup /tmp/lab/src/sub/deep /tmp/lab/src/sub/rotated.log\\nprintf ''%s\\\\n'' ''a'' > ''/tmp/lab/src/a.log''\\nprintf ''%s\\\\n'' ''b'' > ''/tmp/lab/src/b.log''\\nprintf ''%s\\\\n'' ''remember: set debug=true in the conf files'' > ''/tmp/lab/src/notes.txt''\\nprintf ''%s\\\\n'' ''report'' > ''/tmp/lab/src/my report.txt''\\nprintf ''%s\\\\n'' ''old'' > ''/tmp/lab/src/old data.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/old data.log''\\nprintf ''%s\\\\n'' ''tmp1'' > ''/tmp/lab/src/cache1.tmp''\\nprintf ''%s\\\\n'' ''name=app'' ''debug=true'' > ''/tmp/lab/src/app.conf''\\nprintf ''%s\\\\n'' ''c'' > ''/tmp/lab/src/sub/c.log''\\nprintf ''%s\\\\n'' ''xy'' > ''/tmp/lab/src/sub/x y.log''\\nprintf ''%s\\\\n'' ''tmp2'' > ''/tmp/lab/src/sub/cache2.tmp''\\nprintf ''%s\\\\n'' ''name=db'' ''debug=true'' ''port=1'' > ''/tmp/lab/src/sub/db.conf''\\nhead -c 3000 /dev/zero > ''/tmp/lab/src/sub/big1.dat''\\nprintf ''%s\\\\n'' ''notes'' > ''/tmp/lab/src/sub/old_notes.txt''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/old_notes.txt''\\nprintf ''%s\\\\n'' ''d'' > ''/tmp/lab/src/sub/deep/d.log''\\nprintf ''%s\\\\n'' ''tmp3'' > ''/tmp/lab/src/sub/deep/cache3.tmp''\\nprintf ''%s\\\\n'' ''name=net'' ''debug=false'' > ''/tmp/lab/src/sub/deep/net.conf''\\nhead -c 5000 /dev/zero > ''/tmp/lab/src/sub/deep/big2.dat''\\nprintf ''%s\\\\n'' ''trace'' > ''/tmp/lab/src/sub/deep/old trace.log''\\ntouch -d ''2020-01-01 00:00:00'' ''/tmp/lab/src/sub/deep/old trace.log''\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/src/app.conf | cut -d\\" \\" -f1)\\" = \\"84e25a845ef07398931ab210372391e8\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/src/sub/db.conf | cut -d\\" \\" -f1)\\" = \\"e3ec79723a76ba1c1ad2987f7fa4daaf\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/src/sub/deep/net.conf | cut -d\\" \\" -f1)\\" = \\"7c08d7467a8aab0c908965c23867cf0d\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/src/notes.txt | cut -d\\" \\" -f1)\\" = \\"6c99b49a942ea69781bf37c054957887\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app.conf 가 debug=false 로 바뀌었다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/src/app.conf | cut -d\\" \\" -f1)\\" = \\"84e25a845ef07398931ab210372391e8\\" ]"]}, {"label": "sub/db.conf 가 debug=false 로 바뀌었다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/src/sub/db.conf | cut -d\\" \\" -f1)\\" = \\"e3ec79723a76ba1c1ad2987f7fa4daaf\\" ]"]}, {"label": "net.conf 는 그대로다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/src/sub/deep/net.conf | cut -d\\" \\" -f1)\\" = \\"7c08d7467a8aab0c908965c23867cf0d\\" ]"]}, {"label": "notes.txt 는 건드리지 않았다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/src/notes.txt | cut -d\\" \\" -f1)\\" = \\"6c99b49a942ea69781bf37c054957887\\" ]"]}]', '[{"title": "find 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/find.1.html"}, {"title": "xargs 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/xargs.1.html"}, {"title": "grep 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/grep.1.html"}, {"title": "mv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/mv.1.html"}, {"title": "cp 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cp.1.html"}]');
